// Build qualification prompt from lead fields
const record = $input.item.json;
const f = record.fields || {};

const prompt = `You are a sales qualifier for DealDock, a B2B SaaS for Indian Instagram creators.

ICP TARGET:
- Indian solo creator with 40K–250K Instagram followers
- Sells: course, cohort, or 1:1 coaching — their own product, via DMs
- Revenue: ₹6L–₹20L/month estimated
- DM volume: heavy (80–400/day)
- No large team (max 1 VA)

5 YES-SIGNALS (each worth +2 points):
1. Bio link = paid product landing page (Stan Store, Exly, Graphy, Kajabi, Razorpay, custom)
2. Bio CTA reads "DM [KEYWORD]" or "DM for cohort" — routing buyers through inbox
3. Story highlights include Wins/Results/Testimonials/Students (5+ covers)
4. Pinned post is a sales Reel with 200+ comments
5. Recent posts mention cohort numbers ("Batch 6 closing", "last 3 seats")

3 ANTI-SIGNALS (each worth -3 points):
1. No own product — pure brand deal / UGC creator
2. >700K followers + visible team size signal
3. Free-content only, under 20K followers, no monetization signal

LEAD DATA:
- IG Handle: ${f.ig_handle || 'unknown'}
- Followers: ${f.ig_followers || 0}
- Bio: ${(f.ig_bio || '').substring(0, 300)}
- Bio links: ${f.bio_links || 'none'}
- Story highlights: ${f.story_highlights || 'none'}
- Recent post captions (sample): ${(f.recent_posts_sample || '').substring(0, 500)}
- Has product page: ${f.has_product_page || false}
- Has booking link: ${f.has_booking || false}
- Source: ${f.source || 'ig_hashtag'}

Respond in JSON only:
{
  "score": <0-10>,
  "yes_signals_hit": ["list of signals present"],
  "anti_signals_hit": ["list of disqualifiers present"],
  "estimated_revenue_band": "<₹4L | ₹4-10L | ₹10-25L | ₹25L+ | unknown>",
  "niche": "<business|fitness|finance|language|career|design|marketing|mindset|other>",
  "primary_channel": "<IG DM | LinkedIn | Email>",
  "personalization_hook": "<one specific, real observation from their profile to use in outreach — mention a specific post, cohort number, or bio detail>",
  "outreach_priority": "<high|medium|low>",
  "disqualify_reason": "<null or short reason if score < 5>"
}`;

return [{
  json: {
    record_id: record.id,
    ig_handle: f.ig_handle || '',
    ig_followers: f.ig_followers || 0,
    email: f.email || '',
    email_found: f.email_found || false,
    qualification_prompt: prompt
  }
}];

// Parse Claude's JSON response
const claudeResponse = $input.item.json;
const content = claudeResponse?.content?.[0]?.text || '{}';

let parsed;
try {
  // Extract JSON from the response (Claude sometimes wraps in markdown)
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  parsed = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(content);
} catch(e) {
  parsed = {
    score: 0,
    yes_signals_hit: [],
    anti_signals_hit: ['parse_error'],
    estimated_revenue_band: 'unknown',
    niche: 'other',
    primary_channel: 'Email',
    personalization_hook: 'Could not parse AI response',
    outreach_priority: 'low',
    disqualify_reason: 'AI response parse error'
  };
}

const score = parseInt(parsed.score) || 0;
const qualStatus = score >= 7 ? 'qualified' : (score >= 5 ? 'hold' : 'dead');
const emailSequenceActive = score >= 7;

// Get lead info from upstream node
const leadInfo = $('Build Qualification Prompt').item.json;

return [{
  json: {
    record_id: leadInfo.record_id,
    ig_handle: leadInfo.ig_handle,
    email: leadInfo.email,
    email_found: leadInfo.email_found,
    score,
    yes_signals_hit: JSON.stringify(parsed.yes_signals_hit || []),
    anti_signals_hit: JSON.stringify(parsed.anti_signals_hit || []),
    estimated_revenue_band: parsed.estimated_revenue_band || 'unknown',
    niche: parsed.niche || 'other',
    primary_channel: parsed.primary_channel || 'Email',
    personalization_hook: parsed.personalization_hook || '',
    outreach_priority: parsed.outreach_priority || 'low',
    disqualify_reason: parsed.disqualify_reason || null,
    qualification_status: qualStatus,
    email_sequence_active: emailSequenceActive,
    sequence_step: 0
  }
}];

